[workspace.package]
version = "1.0.0"
edition = "2021"
authors = ["OP-DBUS Contributors"]
license = "Apache-2.0"

[workspace.dependencies]
# Internal Crates
op-core = { path = "crates/op-core" }
op-tools = { path = "crates/op-tools" }
op-chat = { path = "crates/op-chat" }
op-http = { path = "crates/op-http" }
op-state = { path = "crates/op-state" }
op-llm = { path = "crates/op-llm" }
op-network = { path = "crates/op-network" }
op-agents = { path = "crates/op-agents" }
op-cache = { path = "crates/op-cache" }
op-introspection = { path = "crates/op-introspection" }
op-dbus-model = { path = "crates/op-dbus-model" }
op-execution-tracker = { path = "crates/op-execution-tracker" }
op-state-store = { path = "crates/op-state-store" }
op-plugins = { path = "crates/op-plugins" }
op-workflows = { path = "crates/op-workflows" }
op-blockchain = { path = "crates/op-blockchain" }
op-inspector = { path = "crates/op-inspector" }
op-mcp = { path = "crates/op-mcp" }
op-web = { path = "crates/op-web" }
op-grpc-bridge = { path = "crates/op-grpc-bridge" }
op-identity = { path = "crates/op-identity" }
op-dbus-mirror = { path = "crates/op-dbus-mirror" }
op-jsonrpc = { path = "crates/op-jsonrpc" }
op-openvswitch-daemon = { path = "crates/op-openvswitch-daemon" }
op-projection = { path = "crates/op-projection" }
op-cozo-store = { path = "crates/op-cozo-store" }
op-s6-systemctl = { path = "crates/op-s6-systemctl" }
op-xray-daemon = { path = "crates/op-xray-daemon" }

# Async
tokio = { version = "1", features = ["full"] }
tokio-stream = "0.1"
futures = "0.3"
async-trait = "0.1"

# Serialization
serde = { version = "1", features = ["derive"] }
simd-json = { version = "0.13", features = ["serde", "serde_impl"] }
serde_json = "1"
serde_yaml = "0.9"
toml = "0.8"
jsonschema = { version = "0.29", default-features = false }

# DBus
zbus = { version = "5", features = ["tokio"] }
zbus_xml = "5"

# Web
axum = { version = "0.7", features = ["ws", "macros", "tokio"] }
tower = "0.4"
tower-http = { version = "0.5", features = ["cors", "fs", "trace", "compression-gzip"] }

# HTTP client
reqwest = { version = "0.11", features = ["json", "stream"] }

# Vector DB
qdrant-client = "1.7"

# Graph DB — Datalog relational-graph-vector DB
# storage-sled: pure-Rust embedded store (avoids the sqlite3 link conflict with rusqlite/op-cache)
cozo = { version = "0.7.6", default-features = false, features = ["rayon", "storage-sled"] }

# Error handling
anyhow = "1"
thiserror = "1"

# Logging
tracing = "0.1"
